mapper.select:
SELECT product_name, code_number, specification, ROUND(price, 2) AS price, MIN(price) AS price_raw, MAX(price) AS price_raw_max, MAX(type) AS type, SUM(in_quantity) - SUM(out_quantity) AS total_stock, SUM((in_quantity - out_quantity) * ROUND(price, 2)) AS total_price FROM ${table}
deleted_at IS NULL
AND target_system = #{targetSystem}
GROUP BY product_name, code_number, specification, ROUND(price, 2) HAVING SUM(in_quantity) - SUM(out_quantity) <> 0 ORDER BY product_name, code_number

SELECT SUM(in_quantity * price) AS total_supply_value
FROM ${table}
WHERE in_quantity > 0
  AND deleted_at IS NULL
  AND date BETWEEN #{start} AND #{end}
